<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Login</title><link rel="stylesheet" href="<?= asset_url('assets/css/admin.css?v=3') ?>"></head><body class="login-page"><form class="login-card" method="post"><h1>Admin Login</h1><?php if($this->session->flashdata('error')):?><div class="alert error"><?= e($this->session->flashdata('error')) ?></div><?php endif;?><?= validation_errors('<div class="alert error">','</div>') ?><?= csrf_field() ?><input name="username" placeholder="Username" value="<?= e(get_cookie('remember_admin_username') ?: set_value('username')) ?>" required><div class="pass"><input id="password" type="password" name="password" placeholder="Password" required><button type="button" onclick="password.type=password.type==='password'?'text':'password'">Show</button></div><label class="check-row"><input type="checkbox" name="remember_username" value="1"> Remember username</label><button class="admin-btn" type="submit">Login</button></form></body></html>
